    def test_graph_adam_adamw_with_explicitly_capturable_param_groups(self):
        # mimicking `_test_graphed_optimizer` maladroitly to pass two param_groups to optimizer.__init__
        n_warmup, n_replay = 3, 2
        for optimizer, second_param_group_capturable in product((torch.optim.Adam, torch.optim.AdamW), (True, False)):
            ref_p1, param1 = (torch.nn.Parameter(torch.ones(1, device="cuda")) for _ in range(2))
            ref_p2, param2 = (torch.nn.Parameter(torch.ones(1, device="cuda")) for _ in range(2))
            grads1, grads2 = ([torch.randn_like(param1) for _ in range(n_warmup + n_replay)] for _ in range(2))
            ref_grads1, ref_grads2 = ([t.clone() for t in tensors] for tensors in (grads1, grads2))
            params = [
                {"params": [param1], "capturable": True},
                {"params": [param2], "capturable": second_param_group_capturable},
            ]
            opt = optimizer(params)
            opt_ = optimizer([
                param1,
                param2 if second_param_group_capturable else None,
            ])
            # Ensure that the optimizer and the manually constructed one produce the same results
            for param in params:
                if param["capturable"]:
                    opt.add_param_group(param)
            for param in params:
                if param["capturable"]:
                    opt_ = optimizer([param["params"][0]] + (param["params"][1] if second_param_group_capturable else []))
            # Verify that the optimizers produce the same results
            for param in params:
                if param["capturable"]:
                    self.assertTrue(torch.allclose(opt.state[param["params"][0]].grad, opt_.state[param["params"][0]].grad))
            # Verify that the optimizers produce the same results for the second param group
            if second_param_group_capturable:
                for param in params:
                    if param["capturable"]:
                        self.assertTrue(torch.allclose(opt.state[param["params"][1]].grad, opt_.state[param["params"][1]].grad))

