    # check for symbolic variable wrapping a SingletonSymNode (fake-ifying causes this)
    return (
        s.node.is_symbolic()
        and s.node.hint is not None
        and isinstance(s.node.hint, torch.SymInt)
        and s.node.hint.node.singleton_int() is not None
    )

