            # We need to check if the hint of the symbolic variable is a SingletonSymNode
            if isinstance(val.hint, torch.SymInt) and val.hint.node.singleton_int() is not None:
                yield val.hint.node.singleton_int()
            else:
                yield val
        else:
            yield val
    else:
        yield val

